try {
  const body = $input.first().json.body;
  const args = body.message.toolCalls[0].function.arguments;
  const toolCallId = body.message.toolCalls[0].id;

  // PKT = UTC+5, so subtract 5 hours for Google Calendar
  const PKT_OFFSET = 5 * 60 * 60 * 1000;

  // Build start time — try ISO first, then parse text
  let startTime;
  const dt = args.appointment_datetime || '';

  if (dt.match(/^\d{4}-\d{2}-\d{2}T/)) {
    // Already ISO format: 2026-06-17T15:00:00
    startTime = new Date(new Date(dt).getTime() - PKT_OFFSET);

  } else {
    // Text format: "Wednesday 17 June at 3PM" or "17 June at 3:00 PM"
    const months = {
      january:0, february:1, march:2, april:3,
      may:4, june:5, july:6, august:7,
      september:8, october:9, november:10, december:11
    };

    // Extract day number
    const dayMatch = dt.match(/(\d{1,2})/);
    const day = dayMatch ? parseInt(dayMatch[1]) : 17;

    // Extract month
    const monthMatch = dt.toLowerCase().match(/(january|february|march|april|may|june|july|august|september|october|november|december)/);
    const month = monthMatch ? months[monthMatch[1]] : 5;

    // Extract hour and AM/PM
    const timeMatch = dt.match(/(\d{1,2})(?::(\d{2}))?\s*(AM|PM)/i);
    let hour = timeMatch ? parseInt(timeMatch[1]) : 9;
    const mins = timeMatch && timeMatch[2] ? parseInt(timeMatch[2]) : 0;
    const ampm = timeMatch ? timeMatch[3].toUpperCase() : 'AM';

    if (ampm === 'PM' && hour !== 12) hour += 12;
    if (ampm === 'AM' && hour === 12) hour = 0;

    // Build date in PKT then convert to UTC
   const pktDate = new Date(2026, month, day, hour, mins, 0, 0);
    startTime = new Date(pktDate.getTime() - PKT_OFFSET);
  }

  const endTime = new Date(startTime.getTime() + 60 * 60 * 1000);

  return [{
    json: {
      toolCallId: toolCallId,
      full_name: args.full_name || 'Patient',
      date_of_birth: args.date_of_birth || '',
      complaint: args.complaint || '',
      referral_type: args.referral_type || '',
      preferred_location: args.preferred_location || '',
      appointment_datetime: dt,
      phone_number: args.phone_number || '',
      startTime: startTime.toISOString(),
      endTime: endTime.toISOString()
    }
  }];

} catch(e) {
  // Return error details so we can debug
  return [{
    json: {
      error: e.message,
      toolCallId: 'error',
      startTime: new Date().toISOString(),
      endTime: new Date(Date.now() + 3600000).toISOString(),
      full_name: 'Debug Patient',
      preferred_location: 'prospect'
    }
  }];
}

