parameters.jsCode:
const webhookData = $('Webhook').first().json;
const toolCallId = webhookData.body.message.toolCalls[0].id;
const location = webhookData.body.message.toolCalls[0].function.arguments.preferred_location;

// Get all booked event start times from Google Calendar
const bookedEvents = $input.all();
const bookedTimes = new Set(
  bookedEvents.map(e => {
    const start = e.json.start?.dateTime;
    return start ? new Date(start).getTime() : null;
  }).filter(Boolean)
);

const PKT_OFFSET = 5 * 60;
const nowUTC = new Date();
const nowPKT = new Date(nowUTC.getTime() + PKT_OFFSET * 60 * 1000);

const businessHours = [9, 10, 11, 14, 15];
const slots = [];

let day = new Date(nowPKT);
day.setDate(day.getDate() + 1);

while (slots.length < 5) {
  const dayOfWeek = day.getDay();
  if (dayOfWeek !== 0) { // skip Sunday
    for (const hour of businessHours) {
      if (slots.length >= 5) break;

      const slotPKT = new Date(day);
      slotPKT.setHours(hour, 0, 0, 0);

      // Convert to UTC for comparison with Google Calendar
      const slotUTC = new Date(slotPKT.getTime() - PKT_OFFSET * 60 * 1000);

      // Skip if already booked
      if (bookedTimes.has(slotUTC.getTime())) continue;

      const dayName = slotPKT.toLocaleDateString('en-AU', { weekday: 'long' });
      const dateName = slotPKT.toLocaleDateString('en-AU', { day: 'numeric', month: 'long' });
      const timeStr = hour >= 12 ? `${hour === 12 ? 12 : hour - 12}:00 PM` : `${hour}:00 AM`;

      slots.push(`${dayName} ${dateName} at ${timeStr}`);
    }
  }
  day.setDate(day.getDate() + 1);
}

const slotText = slots.map((s, i) => `Slot ${i+1}: ${s}`).join('. ');

return [{ json: { toolCallId, location, slotText } }];
